const onLabelAll = () => {
  localStorage.setItem("dm:labelstream:mode", "all");
  store.startLabelStream();
};

const onLabelVisible = () => {
  localStorage.setItem("dm:labelstream:mode", "filtered");
  store.startLabelStream();

const labelStreamMode = localStorage.getItem("dm:labelstream:mode");

// @todo this is dirty way to sync across nested apps
// don't apply filters for "all" on "next_task"
const actionParams = {
  ordering: view.ordering,
  selectedItems: selected?.snapshot ?? { all: false, included: [] },
  filters: {
    conjunction: view.conjunction ?? "and",
    items: view.serializedFilters ?? [],
  },
};

if (actionId === "next_task") {
  if (labelStreamMode === "all") {
    delete actionParams.filters;

    if (actionParams.selectedItems.all === false && actionParams.selectedItems.included.length === 0) {
      delete actionParams.selectedItems;
      delete actionParams.ordering;
    }
  } else if (labelStreamMode === "filtered") {
    delete actionParams.selectedItems;
  }

get snapshot() {
  return {
    all: self.all,
    [self.listName]: Array.from(self.list),
  };
},

get listName() {
  return self.all ? "excluded" : "included";
},

toggleSelectedAll() {
  if (!self.all || !(self.all && self.isIndeterminate)) {
    self.all = !self.all;
  }

  self.list = [];
  self._invokeChangeEvent();
},

const newTask = await this.withinLoadingState(async () => {
  let nextTask;

  if (!isDefined(taskID)) {
    nextTask = await tasks.loadNextTask();
  } else {
    nextTask = await tasks.loadTask(taskID);
  }

const _taskHistory = await this.datamanager.store.taskStore.loadTaskHistory({
  projectId: this.datamanager.store.project.id,
});

this.lsf.setTaskHistory(_taskHistory);

await this.loadUserLabels();

if (this.canPreloadTask && isFF(FF_DEV_1752)) {
  await this.preloadTask();
} else if (this.labelStream) {
  await this.loadTask();
}

onSubmitAnnotation = async () => {
  const exitStream = this.shouldExitStream();
  const loadNext = exitStream ? false : this.shouldLoadNext();
  const result = await this.submitCurrentAnnotation(
    "submitAnnotation",
    async (taskID, body) => {
      return await this.datamanager.apiCall(
        "submitAnnotation",
        { taskID },
        { body },
        // don't react on duplicated annotations error
        { errorHandler: (result) => result.status === 409 },
      );
    },
    false,
    loadNext,
  );

onNextTask = async (nextTaskId, nextAnnotationId) => {
  if (isFF(FF_OPTIC_2)) this.saveDraft();
  this.loadTask(nextTaskId, nextAnnotationId, true);
};
onPrevTask = async (prevTaskId, prevAnnotationId) => {
  if (isFF(FF_OPTIC_2)) this.saveDraft();
  this.loadTask(prevTaskId, prevAnnotationId, true);

this.setLoading(false);

if (!loadNext || this.datamanager.isExplorer) {
  await this.loadTask(taskID, currentAnnotation.pk, true);
} else {
  await this.loadTask();
}

function nextTask() {
  if (self.canGoNextTask) {
    const { taskId, annotationId } =
      self.taskHistory[self.taskHistory.findIndex((x) => x.taskId === self.task.id) + 1];

    getEnv(self).events.invoke("nextTask", taskId, annotationId);
    self.incrementQueuePosition();
  }
}

function prevTask(e, shouldGoBack = false) {
  const length = shouldGoBack
    ? self.taskHistory.length - 1
    : self.taskHistory.findIndex((x) => x.taskId === self.task.id) - 1;

  if (self.canGoPrevTask || shouldGoBack) {
    const { taskId, annotationId } = self.taskHistory[length];

    getEnv(self).events.invoke("prevTask", taskId, annotationId);
    self.incrementQueuePosition(-1);

def postponed_queue(next_task, prepared_tasks, project, user, queue_info):
    if not next_task:
        q = Q(task__project=project, task__isnull=False, was_postponed=True, task__is_labeled=False)
        if flag_set('fflag_fix_back_lsdv_1044_check_annotations_24012023_short', user):
            q &= ~Q(task__annotations__completed_by=user)

        postponed_tasks = user.drafts.filter(q).order_by('updated_at').values_list('task__pk', flat=True)
        if postponed_tasks.exists():
            preserved_order = Case(*[When(pk=pk, then=pos) for pos, pk in enumerate(postponed_tasks)])
            postponed_tasks = prepared_tasks.filter(pk__in=postponed_tasks).order_by(preserved_order)
            next_task = _get_first_unlocked(postponed_tasks, user)
            if next_task is not None:
                next_task.allow_postpone = False
            queue_info = 'Postponed draft queue'

    return next_task, queue_info

not_solved_tasks, user_solved_tasks_array, queue_info, prioritized_low_agreement = get_not_solved_tasks_qs(
    user, project, prepared_tasks, assigned_flag, queue_info
)

if not dm_queue:
    next_task, use_task_lock, queue_info = get_next_task_without_dm_queue(
        user, project, not_solved_tasks, assigned_flag, prioritized_low_agreement
    )

if flag_set('fflag_fix_back_lsdv_4523_show_overlap_first_order_27022023_short'):
    # show tasks with overlap > 1 first
    if not next_task and project.show_overlap_first:
        # don't output anything - just filter tasks with overlap
        logger.debug(f'User={user} tries overlap first from prepared tasks')
        _, tasks_with_overlap = _try_tasks_with_overlap(not_solved_tasks)
        queue_info += 'Show overlap first'
        next_task, queue_info = get_task_from_qs_with_sampling(
            tasks_with_overlap, user_solved_tasks_array, prepared_tasks, user, project, queue_info
        )

if not next_task:
    if dm_queue:
        queue_info += (' & ' if queue_info else '') + 'Data manager queue'
        logger.debug(f'User={user} tries sequence sampling from prepared tasks')
        next_task = not_solved_tasks.first()

    else:
        next_task, queue_info = get_task_from_qs_with_sampling(
            not_solved_tasks, user_solved_tasks_array, prepared_tasks, user, project, queue_info
        )

next_task, queue_info = postponed_queue(next_task, prepared_tasks, project, user, queue_info)

next_task, queue_info = skipped_queue(next_task, prepared_tasks, project, user, queue_info)
